<script setup lang="ts">
defineProps<{modelValue:boolean;title:string;fields:{code:string;label:string;type:string;editable?:boolean;required?:boolean;options?:{label:string;value:string|number|boolean}[]}[];model:Record<string,unknown>;remoteOptions?:Record<string,{label:string;value:string|number|boolean}[]>}>();
const emit = defineEmits<{(e:'submit'):void;(e:'update:modelValue',v:boolean):void;(e:'update:model',v:any):void}>();
</script>
<template><el-dialog :model-value="modelValue" :title="title" width="520px" @update:model-value="emit('update:modelValue',$event)"><el-form label-width="90px"><el-form-item v-for="f in fields.filter((x:any)=>x.editable!==false)" :key="f.code" :label="f.label" :required="f.required"><slot :name="`field-${f.code}`" :field="f" :model="model"><el-input v-if="f.type==='text'||f.type==='textarea'" :type="f.type==='textarea'?'textarea':'text'" :model-value="model[f.code]" @update:model-value="(v:any)=>emit('update:model',{...model,[f.code]:v})"/><el-input-number v-else-if="f.type==='number'" :model-value="model[f.code]" @update:model-value="(v:any)=>emit('update:model',{...model,[f.code]:v})"/><el-select v-else-if="f.type==='select'" :model-value="model[f.code]" @update:model-value="(v:any)=>emit('update:model',{...model,[f.code]:v})"><el-option v-for="o in remoteOptions?.[f.code]||f.options||[]" :key="String(o.value)" :label="o.label" :value="o.value"/></el-select><el-switch v-else-if="f.type==='switch'" :model-value="model[f.code]" @update:model-value="(v:any)=>emit('update:model',{...model,[f.code]:v})"/></slot></el-form-item></el-form><template #footer><el-button @click="emit('update:modelValue',false)">取消</el-button><el-button type="primary" @click="emit('submit')">保存</el-button></template></el-dialog></template>
